<style>    

@media screen and (max-width: 999px) {

	.toggle-menu {
        	font-size: 1.25em;
        	padding-left: 20px;
	}

	#logobanner {
		display: none;
	}

        .menux {
                background-color: #022049;
                color: #ffffff; font-size: 14px !important; 
                position: relative;
                left: 0;
                width: 100%;
                padding: 5px 0 5px 0;
                z-index: 10;
		max-height: 5px;
        }
    }   

    @media screen and (min-width: 1000px) {
        .toggle-menu {
                display: none;
        }


	.menux {
	      	background-color: #022049;
      		color: #fff; 
                font-size: 18px !important; 
      		position: relative;
      		left: 0;
      		width: 100%;
      		padding: 2px 0 2px 0;
      		z-index: 10;
		font-size: 1.3em;
	}
	
    }   

.items-leading {
    padding: 0px !important; 
}

#ja-header .main-inner1 {
    background: #022049; font-size: 14px !important;
}

.main .main-inner1 {
    margin-left: 0 !important;
    margin-right: 0 !important;
}

#ja-search {
    border-bottom: 0px !important; 
}

#ja-top {
    border-left: 0px !important;
}

    .menux input[type="checkbox"] {
      opacity: 0;
      position: absolute;
      left: -9999px;
    }
    .menux a, .menux .toggle-menux {
      color: #0D7811; 
      text-decoration: none;
      -webkit-transition: .3s all ease;
      transition: .3s all ease;
    }
    .menux a:hover, .menux .toggle-menux:hover {
      color: #E3DFE6;
    }
    .menux .toggle-menux {
      display: none;
      padding-left: 10px;
    }
    .menux .toggle-menux:hover {
      cursor: pointer;
    }
    @media screen and (max-width: 999px) {
      .menux .toggle-menux {
        display: block;
      }
    }
    @media screen and (max-width: 999px) {
      .menux .nav {
        background: #022049;
        position: relative;
        height: 100%;
        width: 180px;
	margin-top: 0px;
        left: 0;
        -webkit-transition: .3s all ease;
        transition: .3s all ease;
        -webkit-transform: translateX(-340px);
                transform: translateX(-340px);
        overflow-y: auto;
        font-size: 18px;
      }
      .menux #toggle-responsive:checked ~ .nav {
        -webkit-transform: translateX(0);
                transform: translateX(0);
      }

  	.menux ul > li {
   		 position: relative;
    		padding: 10px 10px 10px 40px;
    		width: 180px;
    		height: 40px;
		margin-bottom: 10px !important;
	}
    }
    .menux label.toggle {
      color: transparent;
      position: relative;
    }
    .menux label.toggle:hover {
      cursor: pointer;
    }
    .menux label.toggle:hover:before {
      width: 0;
      height: 0;
      border-style: solid;
      border-color: transparent transparent transparent #E3DFE6;
      border-width: 5.33333px;
    }
    .menux label.toggle:before {
      content: "";
      font-size: 16px;
      -webkit-transition: .3s all ease;
      transition: .3s all ease;
      position: absolute;
      top: 50%;
      left: 5px;
      -webkit-transform: translateY(0%) rotate(90deg);
              transform: translateY(0%) rotate(90deg);
      width: 0;
      height: 0;
      border-style: solid;
      border-color: transparent transparent transparent #262626;
      border-width: 5.33333px;
    }
    @media screen and (max-width: 999px) {
      .menux label.toggle:before {
        left: 15px;
      }
    }
    .menux ul {
      position: relative;
    }
    .menux ul,
    .menux ul li {
      list-style: none;
      padding: 0;
      margin: 0;
    }
    .menux ul > li {
      position: relative;
      padding: 10px 10px 10px 40px;
    }
    @media screen and (min-width: 1000px) {
      .menux ul > li {
        display: inline;
        padding: 0 10px;
      }
    }
    .menux ul > li > ul {
      position: absolute;
      top: calc(100% + 10px);
      left: 0;
      background: #eee;
      display: none;
    }
    @media screen and (max-width: 999px) {
      .menux ul > li > ul {
        position: relative;
        left: -10px;
        background: rgba(0, 0, 0, 0.1);
        width: calc(100% + 20px);
      }
    }
    @media screen and (min-width: 1000px) {
      .menux ul > li > ul > li {
        display: block;
        white-space: nowrap;
	height: 30px;
        padding: 6px 30px 6px 15px;
      }
      .menux ul > li > ul > li label.toggle:before {
        -webkit-transform: translateY(-50%);
                transform: translateY(-50%);
      }
      .menux ul > li > ul ul {
        left: 100%;
        top: 0;
      }
    }
    .menux ul > li input[type="checkbox"]:checked + ul {
      display: block;
    }



</style>
